   "url": "https://pobeda26.ru/news/zdravookhranenie/2026-11-09/17-tys-stavropoltsev-posetili-shkolu-diabeta-v-2025-godu-376087",
   "src": "Победа 26",
   "photoQuery": "anatomical model desk classroom",
